// Generates the Android app's shared strings from the Windows .resw files
// (specs/007-android-app/contracts/l10n-android.md). The .resw files are the single source of
// every string both apps show; keys stay identical by construction (Constitution IX).
//
//   node tools/l10n/resw-to-android.ts           write android/app/src/main/res/values*/strings_shared.xml
//   node tools/l10n/resw-to-android.ts --check   exit 1 if a generated file would change

import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "../..");
const RESW = join(ROOT, "windows/src/HentaiReader.App/Strings");
const RES = join(ROOT, "android/app/src/main/res");
const LANGUAGES: Record<string, string> = {
  "en-US": "values",
  "de-DE": "values-de",
  "fr-FR": "values-fr",
  "es-ES": "values-es",
  "ja-JP": "values-ja",
  "uk-UA": "values-uk",
};
const CATEGORIES = ["zero", "one", "two", "few", "many", "other"];
const HEADER =
  "<!-- Generated by tools/l10n/resw-to-android.ts from windows/src/HentaiReader.App/Strings. Do not edit:\n" +
  "     change the .resw file and run `npm run l10n:android`. -->\n";

function decodeXml(text: string): string {
  return text
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&#x([0-9a-f]+);/gi, (_, h: string) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, d: string) => String.fromCodePoint(parseInt(d, 10)))
    .replace(/&amp;/g, "&");
}

function readResw(file: string): Map<string, string> {
  const xml = readFileSync(file, "utf8");
  const entries = new Map<string, string>();
  const data = /<data\s+name="([^"]+)"[^>]*>\s*<value>([\s\S]*?)<\/value>/g;
  for (let m = data.exec(xml); m !== null; m = data.exec(xml)) {
    entries.set(decodeXml(m[1]), decodeXml(m[2]));
  }
  return entries;
}

/** A .resw value as an Android string resource body. */
function toAndroid(value: string): string {
  let out = "";
  for (let i = 0; i < value.length; i++) {
    const placeholder = /^\{(\d+)\}/.exec(value.slice(i));
    if (placeholder) {
      out += `%${Number(placeholder[1]) + 1}$s`;
      i += placeholder[0].length - 1;
      continue;
    }
    const c = value[i];
    if (c === "%") out += "%%";
    else if (c === "&") out += "&amp;";
    else if (c === "<") out += "&lt;";
    else if (c === ">") out += "&gt;";
    else if (c === "'") out += "\\'";
    else if (c === '"') out += '\\"';
    else if (c === "\\") out += "\\\\";
    else if (c === "\n") out += "\\n";
    else if (c === "\r") continue;
    else if (c === "\t") out += "\\t";
    else if ((c === "@" || c === "?") && i === 0) out += "\\" + c;
    else out += c;
  }
  // Leading and trailing spaces are kept only inside quotes in Android resources.
  return /^\s|\s$/.test(out) ? `"${out}"` : out;
}

/**
 * Plural families are the keys `<family>_<category>` whose English family has both `_one` and `_other`
 * (a lone `_other` is a vocabulary key such as the tag namespace `Namespace_other`).
 */
function pluralFamilies(english: Map<string, string>): Set<string> {
  const families = new Set<string>();
  for (const key of english.keys()) {
    const family = key.slice(0, -"_other".length);
    if (key.endsWith("_other") && english.has(family + "_one")) families.add(family);
  }
  return families;
}

function familyOf(key: string, families: Set<string>): [string, string] | null {
  for (const category of CATEGORIES) {
    const suffix = "_" + category;
    if (key.endsWith(suffix) && families.has(key.slice(0, -suffix.length))) return [key.slice(0, -suffix.length), category];
  }
  return null;
}

function generate(entries: Map<string, string>, english: Map<string, string>, families: Set<string>, language: string): string {
  const errors: string[] = [];
  const strings: string[] = [];
  const plurals = new Map<string, Map<string, string>>();
  for (const key of [...entries.keys()].sort()) {
    if (!english.has(key)) errors.push(`${language}: key ${key} is not in en-US (English is the source of keys)`);
    if (key.includes(".")) {
      errors.push(`${language}: key ${key} contains a dot (XAML property keys cannot be shared)`);
      continue;
    }
    const family = familyOf(key, families);
    if (family) {
      if (!plurals.has(family[0])) plurals.set(family[0], new Map());
      plurals.get(family[0])!.set(family[1], entries.get(key)!);
    } else {
      strings.push(`    <string name="${key}">${toAndroid(entries.get(key)!)}</string>`);
    }
  }
  const pluralXml = [...plurals.keys()].sort().map((name) => {
    const items = CATEGORIES.filter((c) => plurals.get(name)!.has(c))
      .map((c) => `        <item quantity="${c}">${toAndroid(plurals.get(name)!.get(c)!)}</item>`);
    return `    <plurals name="${name}">\n${items.join("\n")}\n    </plurals>`;
  });
  if (errors.length > 0) throw new Error(errors.join("\n"));
  const lint = language === "en-US" ? ' xmlns:tools="http://schemas.android.com/tools" tools:ignore="UnusedResources,MissingTranslation"' : ' xmlns:tools="http://schemas.android.com/tools" tools:ignore="UnusedResources"';
  return `<?xml version="1.0" encoding="utf-8"?>\n${HEADER}<resources${lint}>\n${[...strings, ...pluralXml].join("\n")}\n</resources>\n`;
}

function main() {
  const check = process.argv.includes("--check");
  const english = readResw(join(RESW, "en-US", "Resources.resw"));
  const families = pluralFamilies(english);
  const stale: string[] = [];
  for (const [tag, folder] of Object.entries(LANGUAGES)) {
    const xml = generate(readResw(join(RESW, tag, "Resources.resw")), english, families, tag);
    const file = join(RES, folder, "strings_shared.xml");
    const current = existsSync(file) ? readFileSync(file, "utf8") : null;
    if (current === xml) continue;
    if (check) {
      stale.push(file);
    } else {
      mkdirSync(dirname(file), { recursive: true });
      writeFileSync(file, xml);
      console.log(`wrote ${file}`);
    }
  }
  if (stale.length > 0) {
    console.error("generated strings are out of date; run `npm run l10n:android`:\n  " + stale.join("\n  "));
    process.exit(1);
  }
}

main();
